package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

class ClonePair3733DifferenceFindingTest {

    private final ClonePair3733 subject = new ClonePair3733();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: side_effect.
     * Difference manifestation: the methods differ in observable side effects.
     */
    @Test
    @BehavioralDifference(DifferenceType.SIDE_EFFECT)
    void methodsWriteDifferentScoresIntoTheOutputArray() {
        // Both methods enumerate the same 14 contingency tables, but method1 stores a linear statistic
        // in the scores array while method2 stores a weighted sum of squared deviations.
        int[] table = {1, 1, 2, 2, 3, 3};
        double[] method1Scores = new double[16];
        double[] method2Scores = new double[16];

        assertEquals(14, subject.method1(method1Scores, table));
        assertEquals(14, subject.method2(method2Scores, table));
        assertEquals(80.0, method1Scores[0]);
        assertEquals(16128.0, method2Scores[0]);
        assertFalse(Arrays.equals(method1Scores, method2Scores));
    }
}
